oxy_webhelp_navlinks = {"modules-d15038e66":{"topics":[{"title":"Shadow Registers","shortdesc":"<p class=\"shortdesc\"> The Shadow Register holds a copy of the internal registers of the TLE9186.      <\/p>","href":"TLE9186_Device_Driver_group__shadow_regs.html","attributes":{"data-id":"group__shadow_regs"},"menu":{"hasChildren":true},"tocID":"group__shadow_regs-d15038e74","next":"group__shadow_regs-d15038e74"},{"title":"Register Information","shortdesc":"<p class=\"shortdesc\"> The addresses, masks and bit-positions are necessary to access each an every bit of the TLE9186 device.      <\/p>","href":"TLE9186_Device_Driver_group__defines.html","attributes":{"data-id":"group__defines"},"menu":{"hasChildren":true},"tocID":"group__defines-d15038e96","next":"group__defines-d15038e96"},{"title":"Initialization Values","shortdesc":"<p class=\"shortdesc\"> The initialization values are needed for the initialization of the register shadow and are based on the reset value of each register.      <\/p>","href":"TLE9186_Device_Driver_group__init_values.html","attributes":{"data-id":"group__init_values"},"menu":{"hasChildren":false},"tocID":"group__init_values-d15038e129","topics":[]},{"title":"Types","shortdesc":"<p class=\"shortdesc\"> The device driver uses AUTOSAR datatypes which need to be defined. This file offers the possibility of either using the platform datatypes or custom data types.      <\/p>","href":"TLE9186_Device_Driver_group__types.html","attributes":{"data-id":"group__types"},"menu":{"hasChildren":false},"tocID":"group__types-d15038e140","topics":[]},{"title":"Function Layer","shortdesc":"<p class=\"shortdesc\"> The Function Layer offers API function for either writing to a register or reading from a register.      <\/p>","href":"TLE9186_Device_Driver_group__func_layer.html","attributes":{"data-id":"group__func_layer"},"menu":{"hasChildren":false},"tocID":"group__func_layer-d15038e151","topics":[]},{"title":"Register Layer","shortdesc":"<p class=\"shortdesc\"> The Register Layer offers API function for either writing to a register or reading from a register.      <\/p>","href":"TLE9186_Device_Driver_group__reg_layer.html","attributes":{"data-id":"group__reg_layer"},"menu":{"hasChildren":false},"tocID":"group__reg_layer-d15038e162","topics":[]},{"title":"Service Layer","shortdesc":"<p class=\"shortdesc\"> The Service Layer is in charge of generating correct MOSI frames based on the information received from the <span class=\"ph apipseudolink\">Register Layer<\/span>. While doing so it calculates the CRC checksum.      <\/p>","href":"TLE9186_Device_Driver_group__serv_layer.html","attributes":{"data-id":"group__serv_layer"},"menu":{"hasChildren":true},"tocID":"group__serv_layer-d15038e173","next":"group__serv_layer-d15038e173"},{"title":"Application Layer","shortdesc":"<p class=\"shortdesc\"> The Application Layer is in charge of utilizing the API functions of the device driver to an application code.      <\/p>","href":"TLE9186_Device_Driver_group__appl_layer.html","attributes":{"data-id":"group__appl_layer"},"menu":{"hasChildren":true},"tocID":"group__appl_layer-d15038e223","next":"group__appl_layer-d15038e223"},{"title":"Hardware Abstraction Layer","shortdesc":"<p class=\"shortdesc\"> The Hardware Abstraction Layer offers platform depended functionality to the device driver. These functions are used by the <span class=\"ph apipseudolink\">Service Layer<\/span> and the <span class=\"ph apipseudolink\">Application Layer<\/span>.      <\/p>","href":"TLE9186_Device_Driver_group__hal.html","attributes":{"data-id":"group__hal"},"menu":{"hasChildren":true},"tocID":"group__hal-d15038e256","next":"group__hal-d15038e256"}]}};